import{_ as e,o,c as p,a4 as l}from"./chunks/framework.DzJZdBQK.js";const m=JSON.parse('{"title":"写作课作业-045","description":"","frontmatter":{"date":"2020-09-02T21:33:25","title":"写作课作业-045","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/045.md","filePath":"posts/homework/045.md"}'),i={name:"posts/homework/045.md"};function a(s,t,r,_,c,n){return o(),p("div",null,[...t[0]||(t[0]=[l("<blockquote><p>9.2写作作业：写一篇“李笑来写作课”的文章。传达“李笑来写作课”值得拥有的感知。[呲牙]。</p></blockquote><ul><li>文字的本质——传递感知</li><li>选择为本——写什么比怎么写重要一万倍</li><li>格式创作——是什么、为什么、怎么样</li><li>逻辑模版——并列、递进、转折</li><li>修辞正议——具象、类比、隐喻</li><li>输入为本——输入、处理、输出</li><li>超级专业——猛</li><li>目的目标——创作的目的是沟通</li></ul><p>以上是写作课的目录，或许你会感动意外。</p><p>看着大家的调查问题，里面写着满满的收获，感觉自己都想买了。等等，自己可是学过的呀？那么问题来了，一样的课，一样的老师，怎么就不一样了呢？其实在写作课里有答案。</p><p>因为输入不一样，有的人只是听，有的人记笔记，有的人反复听，有的人是听写，哪个输入质量高；</p><p>因为处理不一样，有的人听了就听了，有的人听了会想，有的人常听常想，哪个处理能力强；</p><p>因为输出不一样，有的人是不做作业的，有的人隔三差五，有的人日更，哪个输出效果好。</p><p>其实是因为不够猛，对自己不够狠，才会在各个环节做得不够好。</p><p>自己因为贵差点没入群，因为看过《定投改变命运》的三个版本，最终没有错过，也幸亏没有错过。学习的过程中一直在刷新自己写作的认知，充满惊喜。因为听课开始写作，因为写作于是遇见，因为遇见所以成长。</p><p>一切从刚刚开始。</p>",10)])])}const u=e(i,[["render",a]]);export{m as __pageData,u as default};
